/* ── Build WhatsApp contract invitation message (module-level for shared access) ── */
function buildContractWaMsg(
  bookingDate: string,
  submissionId: number | null | undefined,
  chalets: any[],
  contractLink: string,
  period?: string | null,
  isReturning?: boolean,
  tenantName?: string
): string {
  const chalet = chalets?.find((c: any) => c.submissionId === submissionId);
  const cn = chalet?.nameAr ?? "الشاليه";
  const arDays = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];
  const dayN = arDays[new Date(bookingDate + "T12:00:00").getDay()];
  const dual = formatDualDate(bookingDate);
  const gregorianStr = dual.gregorian;
  const hijriStr = dual.hijri.replace(/\s*هـ\s*$/, "") + " هـ";
  /* ── Build period text dynamically from chalet time fields ── */
  const _t = (v: string | null | undefined) => (v ?? "").trim() || null;
  const mIn  = _t(chalet?.morningCheckIn);
  const mOut = _t(chalet?.morningCheckOut);
  const eIn  = _t(chalet?.eveningCheckIn);
  const eOut = _t(chalet?.eveningCheckOut);
  const fIn  = _t(chalet?.fullDayCheckIn);
  const fOut = _t(chalet?.fullDayCheckOut);
  const _range = (ci: string | null, co: string | null) =>
    ci && co ? ` (من ${ci} إلى ${co})` : ci ? ` (من ${ci})` : co ? ` (إلى ${co})` : "";
  const periodMap: Record<string, string> = {
    morning:  "صباحي"   + _range(mIn, mOut),
    evening:  "مسائي"   + _range(eIn, eOut),
    full_day: "يوم كامل" + _range(fIn, fOut),
    full:     "يوم كامل" + _range(fIn, fOut),
  };
  const periodText = (period && periodMap[period]?.trim()) || period || "-";
  const header = (isReturning && tenantName)
    ? `يا هلا وغلا بأخونا ${tenantName}، يسعدنا تكرار زيارتكم لـ ${cn} واعتمدنا حجزكم المبدئي.\n\n`
    : `السلام عليكم ورحمة الله وبركاته،\nنرحب بكم في ${cn} ونشكركم على اختيارنا واعتمدنا حجزكم المبدئي.\n\n`;
  const inviteText = isReturning
    ? "ولإتمام التأكيد النهائي والموثق لحجزكم، يرجى التكرم بالدخول على رابط العقد الرقمي أدناه لتحديث بياناتكم والتوقيع إلكترونياً:\n"
    : "ولإتمام التأكيد النهائي والموثق لحجزكم، يرجى التكرم بالدخول على رابط العقد الرقمي أدناه لتعبئة بياناتكم الرسمية والتوقيع إلكترونياً:\n";
  return encodeURIComponent(
    header +
    "تفاصيل الحجز:\n" +
    "- اليوم: " + dayN + "\n" +
    "- التاريخ الميلادي: " + gregorianStr + "\n" +
    "- التاريخ الهجري: " + hijriStr + "\n" +
    "- الفترة: " + periodText + "\n\n" +
    inviteText +
    contractLink + "\n\n" +
    "حياكم الله، ونتمنى لكم إقامة سعيدة وممتعة"
  );
}

/* ── Digital Contracts Archive Tab ───────────────────────── */
function ContractsArchiveTab() {
  const { toast } = useToast();
  const qc = useQueryClient();
  const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");

  function apiFetch(path: string, opts?: RequestInit) {
    return fetch(`${BASE}/api${path}`, { credentials: "include", ...opts });
  }

  /* ── Logo Settings ── */
  const { data: settSubs = [] } = useQuery<any[]>({
    queryKey: ["contractsTab-submissions"],
    queryFn: async () => { const r = await apiFetch("/submissions"); if (!r.ok) return []; return r.json(); },
  });
  const [settSubId, setSettSubId] = useState<number | null>(null);
  const [logoUrl, setLogoUrl] = useState("");
  const [savingSettings, setSavingSettings] = useState(false);
  const [logoUploading, setLogoUploading] = useState(false);
  const logoInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (settSubs.length > 0 && settSubId === null) setSettSubId((settSubs[0] as any).id);
  }, [settSubs, settSubId]);

  const selectedSub = useMemo(() => settSubs.find((s: any) => s.id === settSubId), [settSubs, settSubId]);

  useEffect(() => {
    if (selectedSub) setLogoUrl((selectedSub as any).logoUrl ?? "");
  }, [selectedSub]);

  async function handleSaveSettings(overrideLogoUrl?: string) {
    if (!settSubId) return;
    setSavingSettings(true);
    try {
      const r = await apiFetch(`/owner/submissions/${settSubId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ logoUrl: (overrideLogoUrl ?? logoUrl).trim() || null }),
      });
      if (!r.ok) throw new Error();
      qc.invalidateQueries({ queryKey: ["contractsTab-submissions"] });
      toast({ title: "تم الحفظ ✓", description: "تم تحديث شعار العقد بنجاح" });
    } catch {
      toast({ title: "خطأ", description: "تعذّر الحفظ", variant: "destructive" });
    } finally { setSavingSettings(false); }
  }

  async function handleLogoFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    setLogoUploading(true);
    try {
      const url = await uploadFile(file);
      if (url) {
        setLogoUrl(url);
        await handleSaveSettings(url);
      } else {
        toast({ title: "خطأ", description: "تعذّر رفع الشعار، حاول مجدداً", variant: "destructive" });
      }
    } finally {
      setLogoUploading(false);
      e.target.value = "";
    }
  }

  /* ── Bookings & Filters ── */
  const [search, setSearch] = useState("");
  const [contractCalView, setContractCalView] = useState<"hijri" | "gregorian">(
    (localStorage.getItem("dashCalDefaultType") as "hijri" | "gregorian") ?? "hijri"
  );
  const [contractMonth, setContractMonth] = useState<string>("all");
  const [contractYear, setContractYear] = useState<string>("");
  const [filterStatus, setFilterStatus] = useState<"all" | "signed" | "pending" | "cancelled">("all");
  const [page, setPage] = useState(1);
  const [dropdownPos, setDropdownPos] = useState<{ id: number; right: number; top: number; up: boolean } | null>(null);

  useEffect(() => {
    if (!dropdownPos) return;
    const close = () => setDropdownPos(null);
    window.addEventListener("scroll", close, true);
    window.addEventListener("resize", close);
    return () => { window.removeEventListener("scroll", close, true); window.removeEventListener("resize", close); };
  }, [dropdownPos]);

  const { data: bookings = [], isLoading } = useQuery<OwnerBooking[]>({
    queryKey: ["contractsArchive-bookings"],
    queryFn: async () => { const r = await apiFetch("/owner/bookings"); if (!r.ok) return []; return r.json(); },
  });

  const { data: ownerChalets = [] } = useQuery<any[]>({
    queryKey: ["contractsArchive-chalets"],
    queryFn: async () => { const r = await apiFetch("/owner/chalets"); if (!r.ok) return []; return r.json(); },
  });

  const returningPhonesSet = useMemo(() => {
    const counts = new Map<string, number>();
    for (const b of bookings) { const p = (b as any).clientPhone ?? ""; if (p) counts.set(p, (counts.get(p) ?? 0) + 1); }
    return new Set([...counts.entries()].filter(([, n]) => n > 1).map(([p]) => p));
  }, [bookings]);

  function contractUrl(id: number) { return `${window.location.origin}${BASE}/contract/${id}`; }
  function copyLink(id: number) {
    navigator.clipboard.writeText(contractUrl(id)).then(() =>
      toast({ title: "تم النسخ ✓", description: "رابط العقد في الحافظة" }),
    );
  }
  function openPrint(id: number) { window.open(contractUrl(id), "_blank"); }

  type StatusKey = "signed" | "pending" | "cancelled";
  function statusBadge(b: OwnerBooking): { key: StatusKey; label: string; cls: string } {
    if (b.cancelledAt)    return { key: "cancelled", label: "ملغي",           cls: "bg-red-50 text-red-600 border-red-200 dark:bg-red-900/20 dark:text-red-400 dark:border-red-700/40" };
    if (b.contractSigned) return { key: "signed",    label: "مُوقَّع ✓",     cls: "bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-700/40" };
    return                       { key: "pending",   label: "قيد الانتظار", cls: "bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-700/40" };
  }

  /* ── Year options built from actual bookings ── */
  const contractYearOptions = useMemo(() => {
    const years = new Set<string>();
    for (const b of bookings) {
      if (!b.bookingDate) continue;
      years.add(getBookingMonthKey(b.bookingDate, contractCalView).split("-")[0]);
    }
    return Array.from(years).sort().reverse();
  }, [bookings, contractCalView]);

  /* ── Month options filtered by selected year ── */
  const monthOptions = useMemo(() => {
    const keySet = new Set<string>();
    for (const b of bookings) {
      if (!b.bookingDate) continue;
      const key = getBookingMonthKey(b.bookingDate, contractCalView);
      if (contractYear && !key.startsWith(contractYear)) continue;
      keySet.add(key);
    }
    return Array.from(keySet).sort();
  }, [bookings, contractCalView, contractYear]);

  const monthFiltered = useMemo(() => {
    if (contractMonth !== "all") {
      return bookings.filter((b) => b.bookingDate && getBookingMonthKey(b.bookingDate, contractCalView) === contractMonth);
    }
    if (contractYear) {
      return bookings.filter((b) => b.bookingDate && getBookingMonthKey(b.bookingDate, contractCalView).startsWith(contractYear));
    }
    return bookings;
  }, [bookings, contractMonth, contractYear, contractCalView]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase().replace(/[٠-٩]/g, d => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)));
    if (!q) return monthFiltered;
    return monthFiltered.filter((b) =>
      String(b.id).includes(q) ||
      (b.clientName ?? "").toLowerCase().includes(q) ||
      (b.clientPhone ?? "").replace(/\D/g, "").includes(q),
    );
  }, [monthFiltered, search]);

  const displayed = useMemo(() => {
    if (filterStatus === "all") return filtered;
    return filtered.filter((b) => statusBadge(b).key === filterStatus);
  }, [filtered, filterStatus]);

  const PAGE_SIZE = 10;
  const totalPages = Math.max(1, Math.ceil(displayed.length / PAGE_SIZE));
  const paginated = useMemo(
    () => displayed.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE),
    [displayed, page],
  );

  useEffect(() => { setPage(1); }, [search, contractMonth, contractCalView, filterStatus]);

  const signed    = bookings.filter((b) => b.contractSigned).length;
  const pending   = bookings.filter((b) => !b.contractSigned && !b.cancelledAt).length;
  const cancelled = bookings.filter((b) => !!b.cancelledAt).length;

  return (
    <div className="max-w-4xl mx-auto py-6 px-4 space-y-5" dir="rtl">

      {/* ── Settings Panel ── */}
      <div className="bg-card rounded-2xl border border-border p-5 space-y-4">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-xl bg-primary/10 flex items-center justify-center shrink-0">
            <Settings className="w-4 h-4 text-primary" />
          </div>
          <div>
            <h3 className="font-bold text-base text-foreground">إعدادات العقد الرقمي</h3>
            <p className="text-xs text-muted-foreground">شعار الشاليه الظاهر في رأس العقد</p>
          </div>
        </div>

        {/* Chalet selector — only when multiple chalets exist */}
        {settSubs.length > 1 && (
          <div className="space-y-1.5">
            <label className="text-xs font-medium text-muted-foreground">اختر الشاليه</label>
            <select
              value={settSubId ?? ""}
              onChange={(e) => setSettSubId(Number(e.target.value))}
              className="w-full rounded-xl border border-border bg-background px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 text-right"
            >
              {settSubs.map((s: any) => (
                <option key={s.id} value={s.id}>{s.name ?? `شاليه #${s.id}`}</option>
              ))}
            </select>
          </div>
        )}

        {/* Logo upload */}
        <div className="space-y-2">
          <label className="text-xs font-medium text-muted-foreground">شعار الشاليه في رأس العقد <span className="font-normal">(اختياري)</span></label>
          <input
            ref={logoInputRef}
            type="file"
            accept="image/png,image/jpeg,image/webp"
            className="hidden"
            onChange={handleLogoFileChange}
          />
          <div className="flex items-center gap-3">
            {/* Preview thumbnail */}
            {logoUrl ? (
              <div className="relative shrink-0">
                <img
                  src={logoUrl}
                  alt="شعار العقد"
                  className="w-16 h-16 rounded-xl object-contain border border-border bg-muted/30 p-1"
                />
                <button
                  type="button"
                  onClick={() => setLogoUrl("")}
                  title="إزالة الشعار"
                  className="absolute -top-1.5 -left-1.5 w-5 h-5 rounded-full bg-destructive text-destructive-foreground flex items-center justify-center text-xs leading-none hover:bg-destructive/80 transition-colors"
                >
                  ×
                </button>
              </div>
            ) : null}
            {/* Upload button / drop zone */}
            <button
              type="button"
              disabled={logoUploading}
              onClick={() => logoInputRef.current?.click()}
              className={`flex-1 flex flex-col items-center justify-center gap-2 rounded-xl border-2 border-dashed py-4 transition-colors text-sm font-medium ${
                logoUploading
                  ? "border-primary/30 bg-primary/5 text-primary cursor-not-allowed"
                  : "border-border hover:border-primary/50 hover:bg-primary/5 text-muted-foreground hover:text-primary cursor-pointer"
              }`}
            >
              {logoUploading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin text-primary" />
                  <span>جارٍ الرفع…</span>
                </>
              ) : (
                <>
                  <Camera className="w-5 h-5" />
                  <span>{logoUrl ? "تغيير الشعار" : "رفع شعار العقد"}</span>
                  <span className="text-xs font-normal opacity-60">PNG · JPG · WEBP</span>
                </>
              )}
            </button>
          </div>
        </div>

        {/* Conditions notice */}
        <div className="bg-blue-50 dark:bg-blue-900/10 border border-blue-200 dark:border-blue-800 rounded-xl p-3 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
          <p className="text-xs text-blue-800 dark:text-blue-300 leading-relaxed">
            📋 <span className="font-semibold">تنويه:</span> يتم سحب شروط وأحكام العقد تلقائيًا من "إعدادات الشاليه".
          </p>
          <button
            type="button"
            onClick={() => window.dispatchEvent(new CustomEvent("switch-dashboard-tab", { detail: "chalets" }))}
            className="shrink-0 text-xs font-medium text-primary border border-primary/30 bg-primary/5 rounded-lg px-3 py-1.5 hover:bg-primary/10 transition-colors whitespace-nowrap"
          >
            ⚙️ تعديل الشروط من إعدادات الشاليه
          </button>
        </div>

        {/* Save */}
        <div className="flex justify-end">
          <button
            type="button"
            disabled={savingSettings || !settSubId}
            onClick={handleSaveSettings}
            className="flex items-center gap-2 px-5 py-2 rounded-xl bg-primary text-primary-foreground text-sm font-semibold hover:bg-primary/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {savingSettings ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
            {savingSettings ? "جارٍ الحفظ…" : "حفظ إعدادات العقد"}
          </button>
        </div>
      </div>

      {/* ── Header ── */}
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center shrink-0">
          <ScrollText className="w-5 h-5 text-primary" />
        </div>
        <div>
          <h2 className="text-xl font-bold text-foreground">قائمة العقود الرقمية</h2>
          <p className="text-sm text-muted-foreground">سجل كامل بجميع عقود الإيجار الموقَّعة والمعلَّقة</p>
        </div>
      </div>

      {/* Stats row */}
      <div className="grid grid-cols-3 gap-3">
        {[
          { suffix: "مُوقَّع",       value: signed,    color: "text-emerald-700 dark:text-emerald-400", bg: "bg-emerald-50 dark:bg-emerald-900/10 border-emerald-200 dark:border-emerald-800" },
          { suffix: "قيد الانتظار", value: pending,   color: "text-amber-700 dark:text-amber-400",   bg: "bg-amber-50 dark:bg-amber-900/10 border-amber-200 dark:border-amber-800" },
          { suffix: "ملغى",         value: cancelled, color: "text-red-600 dark:text-red-400",       bg: "bg-red-50 dark:bg-red-900/10 border-red-200 dark:border-red-800" },
        ].map(({ suffix, value, color, bg }) => {
          const noun = value >= 3 && value <= 10 ? "عقود" : "عقد";
          return (
          <div key={suffix} className={`rounded-xl border px-4 py-3 text-center ${bg}`}>
            <p className={`text-2xl font-bold ${color}`}>{toAr(value)}</p>
            <p className="text-xs text-muted-foreground mt-0.5">{noun} {suffix}</p>
          </div>
        );
        })}
      </div>

      {/* ── Filter Bar ── */}
      <div className="space-y-2">
        {/* Row 1: Unified time filters [هجري|ميلادي] → [Year] → [Month] */}
        <div className="flex items-center gap-2 overflow-x-auto pb-0.5">
          {/* Hijri / Gregorian toggle */}
          <div className="flex rounded-lg overflow-hidden border border-border shrink-0">
            {(["hijri", "gregorian"] as const).map(mode => (
              <button
                key={mode}
                type="button"
                onClick={() => { setContractCalView(mode); setContractMonth("all"); setContractYear(""); }}
                className={`text-xs px-3 py-1.5 font-medium transition-colors ${contractCalView === mode ? "bg-primary text-primary-foreground" : "bg-background text-muted-foreground hover:bg-muted"}`}
              >{mode === "hijri" ? "هجري" : "ميلادي"}</button>
            ))}
          </div>
          {/* Year dropdown */}
          <Select value={contractYear || "__all__"} onValueChange={(yr) => { setContractYear(yr === "__all__" ? "" : yr); setContractMonth("all"); }}>
            <SelectTrigger className="h-9 text-sm rounded-lg border-border w-[7rem] shrink-0" dir="rtl">
              {contractYear
                ? <span className="text-sm font-medium">{contractCalView === "hijri" ? `${toArN(Number(contractYear))} هـ` : `${toArN(Number(contractYear))} م`}</span>
                : <span className="text-sm text-muted-foreground">كل السنوات</span>}
            </SelectTrigger>
            <SelectContent dir="rtl" align="end">
              <SelectItem value="__all__"><span className="text-sm">كل السنوات</span></SelectItem>
              {contractYearOptions.map(yr => (
                <SelectItem key={yr} value={yr}>
                  {contractCalView === "hijri" ? `${toArN(Number(yr))} هـ` : `${toArN(Number(yr))} م`}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          {/* Month dropdown — cascades from year */}
          <Select
            value={!contractYear ? "all" : contractMonth}
            onValueChange={(v) => { if (contractYear) setContractMonth(v); }}
            disabled={!contractYear}
          >
            <SelectTrigger className="h-9 text-sm rounded-lg border-border w-[8rem] shrink-0" dir="rtl">
              {contractMonth !== "all" && contractYear ? (() => {
                const ms = Number(contractMonth.split("-")[1]);
                return contractCalView === "hijri"
                  ? <span className="font-medium">{HIJRI_MONTHS_AR[ms - 1]}</span>
                  : <span className="font-medium">{GREGORIAN_MONTHS_AR[ms - 1]}</span>;
              })() : <span className="text-muted-foreground">كل العقود</span>}
            </SelectTrigger>
            <SelectContent dir="rtl" align="end" className="z-[100]">
              <SelectItem value="all"><span className="text-sm">كل العقود</span></SelectItem>
              {monthOptions.map(key => {
                const [ys, ms] = key.split("-").map(Number);
                const primary = contractCalView === "hijri" ? `${HIJRI_MONTHS_AR[ms-1]} ${toArN(ys)} هـ` : `${GREGORIAN_MONTHS_AR[ms-1]} ${toArN(ys)} م`;
                const corr = getCalCorrespondenceHint(key, contractCalView);
                return (
                  <SelectItem key={key} value={key} textValue={primary}>
                    <div style={{width:"100%",direction:"rtl"}}>
                      <div style={{fontWeight:"600",fontSize:"13px",textAlign:"right"}}>{primary}</div>
                      {corr && <div style={{fontSize:"11px",color:"#888",textAlign:"right",marginTop:"1px"}}>{corr}</div>}
                    </div>
                  </SelectItem>
                );
              })}
            </SelectContent>
          </Select>
        </div>
        {/* Search bar */}
        <div className="relative" dir="rtl">
          <Search className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground pointer-events-none" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="ابحث بالاسم أو رقم الحجز أو الجوال…"
            className="w-full rounded-xl border border-border bg-background pr-10 pl-8 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 text-right"
          />
          {search && (
            <button onClick={() => setSearch("")} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground">
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
        {/* Row 2: Status tabs */}
        <div className="flex gap-1.5 flex-wrap">
          {(["all", "signed", "pending", "cancelled"] as const).map((s) => (
            <button
              key={s}
              onClick={() => setFilterStatus(s)}
              className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${
                filterStatus === s
                  ? "bg-primary text-primary-foreground border-primary"
                  : "bg-background border-border text-muted-foreground hover:text-foreground hover:border-primary/40"
              }`}
            >
              {{ all: "الكل", signed: "مكتمل / موقّع", pending: "بانتظار التوقيع", cancelled: "ملغاة" }[s]}
            </button>
          ))}
        </div>
      </div>

      {/* ── Contracts Table ── */}
      <div className="rounded-2xl border border-border overflow-hidden bg-card">
        {isLoading ? (
          <div className="flex items-center justify-center h-40 gap-2 text-muted-foreground">
            <Loader2 className="w-5 h-5 animate-spin" /> جارٍ التحميل…
          </div>
        ) : displayed.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 gap-3 text-muted-foreground">
            <ScrollText className="w-10 h-10 opacity-20" />
            <p className="text-sm">{search || filterStatus !== "all" || contractMonth !== "all" ? "لا توجد نتائج مطابقة" : "لا توجد عقود حتى الآن"}</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border bg-muted/40 text-right">
                  <th className="px-4 py-3 font-semibold text-muted-foreground w-16">رقم</th>
                  <th className="px-4 py-3 font-semibold text-muted-foreground">اسم المستأجر</th>
                  <th className="px-4 py-3 font-semibold text-muted-foreground hidden sm:table-cell">الجوال</th>
                  <th className="px-4 py-3 font-semibold text-muted-foreground">حالة العقد</th>
                  <th className="px-4 py-3 font-semibold text-muted-foreground hidden md:table-cell">تاريخ الحجز</th>
                  <th className="px-4 py-3 font-semibold text-muted-foreground text-center">الإجراءات</th>
                </tr>
              </thead>
              <tbody>
                {paginated.map((b, idx) => {
                  const status = statusBadge(b);
                  const dualDt = b.bookingDate ? formatDualDate(b.bookingDate) : null;
                  const waUrl = b.clientPhone
                    ? `https://wa.me/${b.clientPhone.replace(/\D/g, "").replace(/^0/, "966")}?text=${buildContractWaMsg(b.bookingDate, b.submissionId, ownerChalets, contractUrl(b.id), (b as any).period, returningPhonesSet.has((b as any).clientPhone ?? ""), (b as any).clientName)}`
                    : null;
                  return (
                    <tr
                      key={b.id}
                      className={`border-b border-border/50 transition-colors hover:bg-muted/20 ${idx % 2 === 0 ? "" : "bg-muted/10"}`}
                    >
                      <td className="px-4 py-3">
                        <span className="font-mono text-xs font-bold text-primary">#{toAr(b.id)}</span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-between gap-2" dir="rtl">
                          <span className="font-medium text-foreground">{b.clientName}</span>
                          {returningPhonesSet.has((b as any).clientPhone ?? "") && (
                            <span className="shrink-0 text-[10px] bg-muted text-muted-foreground rounded-full px-1.5 py-0.5">عميل سابق</span>
                          )}
                        </div>
                      </td>
                      <td className="px-4 py-3 hidden sm:table-cell">
                        {b.clientPhone
                          ? <span className="text-xs text-foreground">{b.clientPhone}</span>
                          : <span className="text-muted-foreground text-xs">—</span>}
                      </td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-semibold border ${status.cls}`}>
                          {status.label}
                        </span>
                      </td>
                      <td className="px-4 py-3 hidden md:table-cell">
                        {dualDt ? (
                          <div className="text-xs">
                            {contractCalView === "hijri" ? (
                              <>
                                <p className="text-foreground font-semibold">{dualDt.hijri.replace(/\s*هـ\s*$/, "")} هـ</p>
                                <p className="text-muted-foreground">{dualDt.gregorian}</p>
                              </>
                            ) : (
                              <>
                                <p className="text-foreground font-semibold">{dualDt.gregorian} م</p>
                                <p className="text-muted-foreground">{dualDt.hijri.replace(/\s*هـ\s*$/, "")} هـ</p>
                              </>
                            )}
                          </div>
                        ) : "—"}
                      </td>
                      {/* Actions dropdown */}
                      <td className="px-4 py-3 text-center">
                        <div className="relative inline-block">
                          <button
                            type="button"
                            onClick={(e) => {
                              if (dropdownPos?.id === b.id) {
                                setDropdownPos(null);
                              } else {
                                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
                                const up = window.innerHeight - rect.bottom < 200;
                                setDropdownPos({
                                  id: b.id,
                                  right: window.innerWidth - rect.right,
                                  top: up ? window.innerHeight - rect.top + 4 : rect.bottom + 4,
                                  up,
                                });
                              }
                            }}
                            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-border bg-background text-xs font-medium text-foreground hover:bg-muted/60 hover:border-primary/40 transition-colors"
                          >
                            الإجراءات
                            <ChevronDown className={`w-3.5 h-3.5 text-muted-foreground transition-transform ${dropdownPos?.id === b.id ? "rotate-180" : ""}`} />
                          </button>
                          {dropdownPos?.id === b.id && createPortal(
                            <>
                              <div className="fixed inset-0 z-[9998]" onClick={() => setDropdownPos(null)} />
                              <div
                                className="fixed z-[9999] w-48 rounded-xl border border-border bg-card shadow-xl py-1"
                                style={{ direction: "rtl", right: dropdownPos.right, ...(dropdownPos.up ? { bottom: dropdownPos.top } : { top: dropdownPos.top }) }}
                              >
                                <button
                                  type="button"
                                  onClick={() => { openPrint(b.id); setDropdownPos(null); }}
                                  className="w-full flex items-center gap-2.5 px-3 py-2 text-right text-sm hover:bg-muted/60 transition-colors text-foreground"
                                >
                                  📄 عرض العقد
                                </button>
                                {waUrl && (
                                  <a
                                    href={waUrl}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    onClick={() => setDropdownPos(null)}
                                    className="w-full flex items-center gap-2.5 px-3 py-2 text-right text-sm hover:bg-muted/60 transition-colors text-foreground"
                                  >
                                    💬 إرسال عبر الواتساب
                                  </a>
                                )}
                                <button
                                  type="button"
                                  onClick={() => { openPrint(b.id); setDropdownPos(null); }}
                                  className="w-full flex items-center gap-2.5 px-3 py-2 text-right text-sm hover:bg-muted/60 transition-colors text-foreground"
                                >
                                  🖨️ طباعة العقد
                                </button>
                                <button
                                  type="button"
                                  onClick={() => { copyLink(b.id); setDropdownPos(null); }}
                                  className="w-full flex items-center gap-2.5 px-3 py-2 text-right text-sm hover:bg-muted/60 transition-colors text-foreground"
                                >
                                  🔗 نسخ رابط العقد
                                </button>
                              </div>
                            </>,
                            document.body
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
        {!isLoading && displayed.length > 0 && (
          <div className="px-4 py-3 border-t border-border/50 bg-muted/20 flex items-center justify-between gap-2 flex-wrap" dir="rtl">
            {/* Counter */}
            <span className="text-xs text-muted-foreground">
              {(() => {
                const from = (page - 1) * PAGE_SIZE + 1;
                const to   = Math.min(page * PAGE_SIZE, displayed.length);
                const t    = displayed.length;
                const noun = (n: number) => n >= 3 && n <= 10 ? "عقود" : "عقد";
                return t <= PAGE_SIZE
                  ? `${toAr(t)} ${noun(t)}`
                  : `عرض ${toAr(from)} - ${toAr(to)} من أصل ${toAr(t)} ${noun(t)}`;
              })()}
            </span>
            {/* Page nav */}
            {totalPages > 1 && (
              <div className="flex items-center gap-1">
                <button
                  type="button"
                  disabled={page === 1}
                  onClick={() => setPage(p => p - 1)}
                  className="h-7 px-2.5 rounded-lg border border-border text-xs font-semibold bg-background text-foreground hover:bg-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >السابق</button>
                {Array.from({ length: totalPages }, (_, i) => i + 1)
                  .filter(n => n === 1 || n === totalPages || Math.abs(n - page) <= 1)
                  .reduce<(number | "…")[]>((acc, n, i, arr) => {
                    if (i > 0 && (n as number) - (arr[i - 1] as number) > 1) acc.push("…");
                    acc.push(n);
                    return acc;
                  }, [])
                  .map((n, i) =>
                    n === "…"
                      ? <span key={`sep-${i}`} className="text-xs text-muted-foreground px-1">…</span>
                      : <button
                          key={n}
                          type="button"
                          onClick={() => setPage(n as number)}
                          className={`h-7 w-7 rounded-lg border text-xs font-semibold transition-colors ${page === n ? "bg-primary text-primary-foreground border-primary" : "bg-background border-border text-foreground hover:bg-muted"}`}
                        >{toAr(n as number)}</button>
                  )}
                <button
                  type="button"
                  disabled={page === totalPages}
                  onClick={() => setPage(p => p + 1)}
                  className="h-7 px-2.5 rounded-lg border border-border text-xs font-semibold bg-background text-foreground hover:bg-muted disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >التالي</button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

/* ── Owner Support Center Tab ────────────────────────────── */
interface OwnerSupportMsg {
  id: number;
  subject: string;
  message: string;
  status: string;
  admin_reply: string | null;
  admin_reply_at: string | null;
  is_read_by_owner: boolean;
  created_at: string;
}

const SUPPORT_STATUS_AR: Record<string, { label: string; color: string }> = {
  new:         { label: "قيد المراجعة", color: "text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-700/40" },
  in_progress: { label: "تم الرد",      color: "text-blue-600 dark:text-blue-400 bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-700/40" },
  resolved:    { label: "مُغلق",         color: "text-green-600 dark:text-green-400 bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-700/40" },
};

function OwnerSupportTab() {
  const { toast } = useToast();
  const qc = useQueryClient();
  const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
  function apiFetch(path: string, opts?: RequestInit) {
    return fetch(`${BASE}/api${path}`, { credentials: "include", headers: { "Content-Type": "application/json", ...(opts?.headers ?? {}) }, ...opts });
  }

  const SUBJECTS = [
    "طلب تعديل تقني",
    "مشكلة في لوحة التحكم",
    "اقتراح ميزة جديدة",
    "طلب تحديث بيانات العقار",
    "استفسار عن الاشتراك",
    "أخرى",
  ];

  const [subject,     setSubject]     = useState("");
  const [message,     setMessage]     = useState("");
  const [submitting,  setSubmitting]  = useState(false);
  const [submitted,   setSubmitted]   = useState(false);
  const [error,       setError]       = useState("");
  const [expandedId,  setExpandedId]  = useState<number | null>(null);
  const [showForm,    setShowForm]    = useState(false);

  /* Fetch message history */
  const { data: history = [], isLoading: histLoading } = useQuery<OwnerSupportMsg[]>({
    queryKey: ["owner", "support-requests"],
    queryFn: async () => {
      const r = await apiFetch("/owner/support-requests");
      if (!r.ok) return [];
      return r.json();
    },
    refetchInterval: 30_000,
  });

  async function markRead(id: number) {
    await apiFetch(`/owner/support-requests/${id}/mark-read`, { method: "POST" });
    qc.invalidateQueries({ queryKey: ["owner", "support-requests"] });
    qc.invalidateQueries({ queryKey: ["owner", "support-unread-count"] });
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError("");
    if (!subject) { setError("اختر الموضوع"); return; }
    if (!message.trim() || message.trim().length < 10) { setError("الرجاء كتابة وصف مفصّل (١٠ أحرف على الأقل)"); return; }
    setSubmitting(true);
    try {
      const r = await apiFetch("/owner/support-request", {
        method: "POST",
        body: JSON.stringify({ subject, message: message.trim() }),
      });
      const d = await r.json().catch(() => null);
      if (!r.ok) { setError(d?.error ?? "حدث خطأ، يرجى المحاولة مرة أخرى"); return; }
      setSubmitted(true);
      setShowForm(false);
      qc.invalidateQueries({ queryKey: ["owner", "support-requests"] });
      toast({ title: "تم الإرسال ✓", description: "سيتواصل معك فريق الدعم في أقرب وقت" });
    } catch { setError("تعذّر الاتصال بالخادم"); }
    finally { setSubmitting(false); }
  }

  const unreadReplies = history.filter((m) => m.admin_reply && !m.is_read_by_owner).length;

  return (
    <div className="max-w-2xl mx-auto space-y-5 py-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
            <MessageSquare className="w-5 h-5 text-primary" />
          </div>
          <div>
            <h2 className="text-base font-bold text-foreground">مركز الدعم والطلبات</h2>
            <p className="text-xs text-muted-foreground">أرسل طلبك التقني أو اقتراحك مباشرةً لفريق تكية</p>
          </div>
        </div>
        <Button
          size="sm"
          onClick={() => { setShowForm(!showForm); setSubmitted(false); setSubject(""); setMessage(""); setError(""); }}
          className="gap-1.5"
        >
          <Send className="w-3.5 h-3.5" />
          طلب جديد
        </Button>
      </div>

      {/* Unread notification */}
      {unreadReplies > 0 && (
        <div className="flex items-center gap-2.5 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-700/40 rounded-xl px-4 py-2.5">
          <span className="w-2.5 h-2.5 rounded-full bg-blue-500 animate-pulse shrink-0" />
          <p className="text-sm text-blue-700 dark:text-blue-300 font-medium">
            لديك {unreadReplies === 1 ? "رد جديد" : `${unreadReplies} ردود جديدة`} من فريق تكية
          </p>
        </div>
      )}

      {/* Send form */}
      {showForm && !submitted && (
        <form onSubmit={handleSubmit} className="bg-card border border-border rounded-2xl p-6 space-y-5">
          <div className="space-y-2">
            <label className="text-sm font-semibold">الموضوع <span className="text-destructive">*</span></label>
            <div className="flex flex-wrap gap-2">
              {SUBJECTS.map((s) => (
                <button
                  key={s}
                  type="button"
                  onClick={() => setSubject(s)}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-colors ${
                    subject === s
                      ? "bg-primary text-primary-foreground border-primary"
                      : "bg-muted text-muted-foreground border-border hover:border-primary hover:text-primary"
                  }`}
                >{s}</button>
              ))}
            </div>
          </div>
          <div className="space-y-1.5">
            <label className="text-sm font-semibold">
              تفاصيل الطلب <span className="text-destructive">*</span>
              <span className="text-xs text-muted-foreground font-normal mr-2">صِف المشكلة أو الطلب بوضوح</span>
            </label>
            <Textarea
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              placeholder="مثال: لاحظت أن لوحة التقويم لا تحفظ الأيام المغلقة بشكل صحيح عند..."
              rows={5}
              dir="rtl"
              className="resize-none"
            />
            <p className="text-xs text-muted-foreground text-left">{message.length} حرف</p>
          </div>
          {error && <p className="text-sm text-destructive font-medium">{error}</p>}
          <div className="flex gap-2">
            <Button type="button" variant="outline" className="flex-1" onClick={() => setShowForm(false)}>إلغاء</Button>
            <Button type="submit" className="flex-1 gap-2" disabled={submitting}>
              {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
              إرسال الطلب
            </Button>
          </div>
        </form>
      )}

      {submitted && (
        <div className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-700 rounded-2xl p-6 text-center space-y-3">
          <CheckCircle className="w-12 h-12 text-green-500 mx-auto" />
          <p className="font-bold text-green-700 dark:text-green-400">تم إرسال طلبك بنجاح!</p>
          <p className="text-muted-foreground text-sm">سيتواصل معك فريق دعم تكية قريباً.</p>
          <Button variant="outline" size="sm" onClick={() => { setSubmitted(false); setShowForm(false); }}>حسناً</Button>
        </div>
      )}

      {/* Message history */}
      <div className="space-y-3">
        <h3 className="text-sm font-bold text-foreground">سجل المراسلات</h3>
        {histLoading ? (
          <div className="text-center py-8 text-muted-foreground"><Loader2 className="w-5 h-5 animate-spin mx-auto" /></div>
        ) : history.length === 0 ? (
          <div className="text-center py-10 bg-muted/30 border border-border rounded-xl">
            <MessageSquare className="w-8 h-8 text-muted-foreground/40 mx-auto mb-2" />
            <p className="text-muted-foreground text-sm">لا توجد رسائل سابقة</p>
            <p className="text-muted-foreground/60 text-xs mt-1">أرسل طلبك الأول عبر زر "طلب جديد" أعلاه</p>
          </div>
        ) : (
          history.map((msg) => {
            const isExp = expandedId === msg.id;
            const statusInfo = SUPPORT_STATUS_AR[msg.status] ?? { label: msg.status, color: "text-muted-foreground bg-muted border-border" };
            const hasUnread = msg.admin_reply && !msg.is_read_by_owner;
            return (
              <div
                key={msg.id}
                className={`border rounded-xl overflow-hidden transition-all ${hasUnread ? "border-blue-400 dark:border-blue-600" : "border-border"}`}
              >
                <div
                  className="flex items-center gap-3 px-4 py-3 cursor-pointer hover:bg-muted/40 transition-colors"
                  onClick={() => {
                    setExpandedId(isExp ? null : msg.id);
                    if (!isExp && hasUnread) markRead(msg.id);
                  }}
                >
                  {hasUnread && <span className="w-2 h-2 rounded-full bg-blue-500 shrink-0 animate-pulse" />}
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-foreground truncate">{msg.subject}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">{new Date(msg.created_at).toLocaleDateString("ar-SA", { year: "numeric", month: "short", day: "numeric" })}</p>
                  </div>
                  <span className={`text-[10px] px-2 py-0.5 rounded-full border font-medium shrink-0 ${statusInfo.color}`}>{statusInfo.label}</span>
                  {msg.admin_reply && <span className="text-[10px] bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 border border-green-200 dark:border-green-700/40 px-2 py-0.5 rounded-full shrink-0">رد متاح</span>}
                  <ChevronDown className={`w-4 h-4 text-muted-foreground shrink-0 transition-transform ${isExp ? "rotate-180" : ""}`} />
                </div>
                {isExp && (
                  <div className="border-t border-border bg-muted/20 px-4 py-4 space-y-4">
                    {/* Owner message */}
                    <div>
                      <p className="text-xs text-muted-foreground mb-1.5 font-medium">رسالتك:</p>
                      <div className="bg-background border border-border rounded-lg p-3 text-sm text-foreground leading-relaxed whitespace-pre-wrap">{msg.message}</div>
                    </div>
                    {/* Admin reply */}
                    {msg.admin_reply && (
                      <div>
                        <p className="text-xs text-blue-600 dark:text-blue-400 mb-1.5 font-medium flex items-center gap-1.5">
                          <Send className="w-3 h-3" /> رد فريق تكية {msg.admin_reply_at ? `— ${new Date(msg.admin_reply_at).toLocaleDateString("ar-SA", { year: "numeric", month: "short", day: "numeric" })}` : ""}:
                        </p>
                        <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-600/30 rounded-lg p-3 text-sm text-blue-900 dark:text-blue-200 leading-relaxed whitespace-pre-wrap">{msg.admin_reply}</div>
                      </div>
                    )}
                    {!msg.admin_reply && (
                      <p className="text-xs text-muted-foreground italic">لم يتم الرد بعد. سيتواصل فريق تكية معك في أقرب وقت.</p>
                    )}
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>

      {/* Info note */}
      <div className="bg-muted/50 border border-border rounded-xl px-4 py-3 text-xs text-muted-foreground leading-relaxed">
        <p className="font-semibold text-foreground mb-1">ملاحظة</p>
        <p>يتم مراجعة الطلبات خلال ٢٤–٤٨ ساعة. للاستفسارات العاجلة تواصل معنا مباشرةً عبر الواتساب من صفحة "اتصل بنا".</p>
      </div>
    </div>
  );
}

/* ── Owner Account Settings Tab ────────────────────────────── */
function OwnerProfileTab() {
  const { toast } = useToast();
  const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
  function apiFetch(path: string, opts?: RequestInit) {
    return fetch(`${BASE}/api${path}`, { credentials: "include", headers: { "Content-Type": "application/json", ...(opts?.headers ?? {}) }, ...opts });
  }

  /* ── form fields ── */
  const [fullName, setFullName] = useState("");
  const [phone, setPhone]       = useState("");
  const [email, setEmail]       = useState("");

  /* ── baselines for dirty-detection ── */
  const [initName,  setInitName]  = useState("");
  const [initPhone, setInitPhone] = useState("");
  const [initEmail, setInitEmail] = useState("");

  /* ── password-change section ── */
  const [showPwSection, setShowPwSection]   = useState(false);
  const [currentPw, setCurrentPw]           = useState("");
  const [newPw, setNewPw]                   = useState("");
  const [confirmPw, setConfirmPw]           = useState("");
  const [showCurPw, setShowCurPw]           = useState(false);
  const [showNewPw, setShowNewPw]           = useState(false);
  const [showConPw, setShowConPw]           = useState(false);

  /* ── multi-step secure flow for email/phone changes ── */
  type SecureStep = "idle" | "password" | "otp";
  const [secureStep, setSecureStep]     = useState<SecureStep>("idle");
  const [securePw, setSecurePw]         = useState("");
  const [showSecPw, setShowSecPw]       = useState(false);
  const [secureOtp, setSecureOtp]       = useState("");
  const [otpSentTo, setOtpSentTo]       = useState("");
  const [sendingOtp, setSendingOtp]     = useState(false);
  const [verifyingOtp, setVerifyingOtp] = useState(false);

  /* ── WhatsApp notification settings (unified) ── */
  const [waSubscribe,      setWaSubscribe]      = useState(false);
  const [waReviewEnabled,  setWaReviewEnabled]  = useState(false);
  const [waSupportEnabled, setWaSupportEnabled] = useState(false);
  const [waUnifiedPhone,   setWaUnifiedPhone]   = useState("");
  const [savingWa,         setSavingWa]         = useState(false);

  /* ── Calendar preferences (seeded from DB via localStorage on load) ── */
  const [bookingsCalPrefLocal, setBookingsCalPrefLocal] = useState<"hijri" | "gregorian">(
    (localStorage.getItem("dashCalDefaultType") as "hijri" | "gregorian") ?? "hijri"
  );
  const [reportsCalPrefLocal, setReportsCalPrefLocal] = useState<"gregorian" | "hijri">(
    (localStorage.getItem("revCalType") as "gregorian" | "hijri") ?? "gregorian"
  );
  const [salaryCalPrefLocal, setSalaryCalPrefLocal] = useState<"gregorian" | "hijri">(
    (localStorage.getItem("staffCalDefault") as "gregorian" | "hijri") ?? "gregorian"
  );

  /* ── page-level state ── */
  const [loading,    setLoading]    = useState(true);
  const [saving,     setSaving]     = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);

  useEffect(() => {
    setFetchError(null);
    Promise.all([
      apiFetch("/owner/profile").then(async (r) => {
        const d = await r.json().catch(() => null);
        console.log("[OwnerProfileTab] API response:", d);
        if (!r.ok) { setFetchError(d?.error ?? "تعذّر تحميل بيانات الحساب"); return null; }
        if (d) {
          const n = d.fullName ?? "", ph = d.phone ?? "", em = d.email ?? "";
          console.log("[OwnerProfileTab] Setting fields — name:", n, "phone:", ph, "email:", em);
          setFullName(n); setInitName(n);
          setPhone(ph);   setInitPhone(ph);
          setEmail(em);   setInitEmail(em);
          setWaSubscribe(!!d.whatsappNewsSubscribe);
          return ph;
        }
        return null;
      }).catch(() => { setFetchError("تعذّر الاتصال بالخادم"); return null; }),
      apiFetch("/owner/notification-settings")
        .then(async (r) => r.ok ? r.json() : null)
        .catch(() => null),
    ]).then(([mainPhone, nd]) => {
      if (nd) {
        setWaReviewEnabled(nd.waEnabled ?? false);
        setWaSupportEnabled(nd.waSupportEnabled ?? false);
        const raw = nd.waPhone ?? "";
        const formatted = raw.startsWith("966") ? "0" + raw.slice(3) : raw;
        setWaUnifiedPhone(formatted || mainPhone || "");
      } else if (mainPhone) {
        setWaUnifiedPhone(mainPhone);
      }
    }).finally(() => setLoading(false));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function normalizeWaPhone(raw: string): string | null {
    const digits = raw.replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d))).replace(/\D/g, "");
    if (!digits) return null;
    if (digits.startsWith("0")) return "966" + digits.slice(1);
    if (digits.startsWith("5") && digits.length === 9) return "966" + digits;
    return digits;
  }

  function toLatinDigits(val: string): string {
    return val.replace(/[٠-٩]/g, (d) => String("٠١٢٣٤٥٦٧٨٩".indexOf(d)));
  }

  function toArabicDigits(val: string): string {
    return val.replace(/[0-9]/g, (d) => "٠١٢٣٤٥٦٧٨٩"[parseInt(d)]);
  }

  async function saveWaSettings() {
    setSavingWa(true);
    try {
      await Promise.all([
        apiFetch("/owner/notification-settings", {
          method: "PATCH",
          body: JSON.stringify({ waEnabled: waReviewEnabled, waSupportEnabled, waPhone: normalizeWaPhone(waUnifiedPhone) }),
        }),
        apiFetch("/owner/profile/whatsapp-subscribe", {
          method: "PATCH",
          body: JSON.stringify({ subscribe: waSubscribe }),
        }),
      ]);
      toast({ title: "تم الحفظ ✓", description: "تم تحديث إعدادات الإشعارات عبر الواتساب" });
    } catch {
      toast({ title: "خطأ", description: "تعذّر حفظ الإعدادات", variant: "destructive" });
    } finally { setSavingWa(false); }
  }

  /* dirty-detection */
  const nameChanged  = fullName.trim() !== initName.trim();
  const phoneChanged = phone.trim()    !== initPhone.trim();
  const emailChanged = email.trim().toLowerCase() !== initEmail.trim().toLowerCase();
  const sensitiveChanged = phoneChanged || emailChanged;
  const pwEdited = showPwSection && (currentPw || newPw || confirmPw);
  const hasChanges = nameChanged || sensitiveChanged || pwEdited;

  /* ── Save (non-sensitive: name / password only) ── */
  async function handleSave() {
    if (!fullName.trim()) { toast({ title: "الاسم مطلوب", variant: "destructive" }); return; }
    if (sensitiveChanged) { setSecureStep("password"); setSecurePw(""); setSecureOtp(""); return; }
    if (showPwSection) {
      if (!currentPw) { toast({ title: "كلمة المرور الحالية مطلوبة", variant: "destructive" }); return; }
      if (newPw.length < 6) { toast({ title: "كلمة المرور الجديدة يجب أن تكون ٦ أحرف على الأقل", variant: "destructive" }); return; }
      if (newPw !== confirmPw) { toast({ title: "كلمتا المرور غير متطابقتين", variant: "destructive" }); return; }
    }
    setSaving(true);
    try {
      const body: Record<string, string> = { fullName: fullName.trim() };
      if (showPwSection && currentPw && newPw) { body.currentPassword = currentPw; body.newPassword = newPw; }
      const r = await apiFetch("/owner/profile", { method: "PUT", body: JSON.stringify(body) });
      const d = await r.json();
      if (!r.ok) { toast({ title: "خطأ", description: d.error ?? "فشل الحفظ", variant: "destructive" }); return; }
      toast({ title: "تم الحفظ ✓", description: "تم تحديث بيانات حسابك بنجاح" });
      setInitName(fullName.trim());
      setCurrentPw(""); setNewPw(""); setConfirmPw(""); setShowPwSection(false);
    } finally { setSaving(false); }
  }

  /* ── Step 1: verify password & send OTP ── */
  async function handleSendOtp() {
    if (!securePw) { toast({ title: "كلمة المرور مطلوبة", variant: "destructive" }); return; }
    setSendingOtp(true);
    try {
      const body: Record<string, string> = { currentPassword: securePw };
      if (emailChanged) body.newEmail = email.trim();
      else if (phoneChanged) body.newPhone = phone.trim();
      const r = await apiFetch("/owner/profile/request-change", { method: "POST", body: JSON.stringify(body) });
      const d = await r.json();
      if (!r.ok) { toast({ title: "خطأ", description: d.error ?? "فشل التحقق", variant: "destructive" }); return; }
      setOtpSentTo(d.otpSentTo ?? "");
      setSecureStep("otp");
      setSecureOtp("");
    } finally { setSendingOtp(false); }
  }

  /* ── Step 2: verify OTP & save all changes ── */
  async function handleVerifyAndSave() {
    if (secureOtp.length < 6) { toast({ title: "رمز التحقق يجب أن يكون ٦ أرقام", variant: "destructive" }); return; }
    setVerifyingOtp(true);
    try {
      const body: Record<string, string> = {
        fullName: fullName.trim(),
        phone:    phone.trim(),
        email:    email.trim().toLowerCase(),
        otp:      secureOtp.trim(),
        otpTarget: otpSentTo,
        sensitiveChange: "true",
      };
      const r = await apiFetch("/owner/profile", { method: "PUT", body: JSON.stringify(body) });
      const d = await r.json();
      if (!r.ok) { toast({ title: "خطأ", description: d.error ?? "رمز التحقق غير صحيح", variant: "destructive" }); return; }
      toast({ title: "تم الحفظ ✓", description: "تم تحديث بيانات حسابك بنجاح" });
      setInitName(fullName.trim());
      setInitPhone(phone.trim());
      setInitEmail(email.trim().toLowerCase());
      setSecureStep("idle");
      setSecurePw(""); setSecureOtp("");
    } finally { setVerifyingOtp(false); }
  }

  function cancelSecure() { setSecureStep("idle"); setSecurePw(""); setSecureOtp(""); }

  if (loading) return <div className="py-12 flex justify-center"><Loader2 className="w-6 h-6 animate-spin text-primary" /></div>;

  return (
    <div className="max-w-lg mx-auto space-y-5 py-4">
      {fetchError && (
        <div className="bg-destructive/10 border border-destructive/30 rounded-xl px-4 py-3 text-sm text-destructive font-medium text-right">
          {fetchError}
        </div>
      )}

      <div className="bg-card border border-border rounded-2xl p-6 space-y-5">
        {/* Header */}
        <div className="flex items-center gap-3 mb-2">
          <div className="w-10 h-10 rounded-full bg-primary/10 flex items-center justify-center">
            <Settings className="w-5 h-5 text-primary" />
          </div>
          <div>
            <h2 className="text-base font-bold text-foreground">إعدادات الحساب</h2>
            <p className="text-xs text-muted-foreground">تعديل بياناتك الشخصية</p>
          </div>
        </div>

        {/* ══════════ Normal editing form ══════════ */}
        {secureStep === "idle" && (
          <>
            {/* Full name */}
            <div className="space-y-1.5">
              <label className="text-sm font-semibold">الاسم الكامل <span className="text-destructive">*</span></label>
              <Input value={fullName} onChange={(e) => setFullName(e.target.value)} className="text-right" placeholder="اسمك الكامل" />
            </div>

            {/* Phone */}
            <div className="space-y-1.5">
              <label className="text-sm font-semibold flex items-center gap-1.5">
                رقم الجوال
                {phoneChanged && <span className="text-[10px] bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded-full font-bold">تم التغيير</span>}
              </label>
              <Input
                value={toAr(phone)}
                onChange={(e) => setPhone(fromAr(e.target.value))}
                className="text-right"
                placeholder="٠٥xxxxxxxx"
                type="text"
                inputMode="numeric"
              />
            </div>

            {/* Email — editable */}
            <div className="space-y-1.5">
              <label className="text-sm font-semibold flex items-center gap-1.5">
                البريد الإلكتروني
                {emailChanged && <span className="text-[10px] bg-amber-100 text-amber-700 px-1.5 py-0.5 rounded-full font-bold">تم التغيير</span>}
              </label>
              <Input
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="text-right"
                placeholder="example@email.com"
                type="email"
                dir="ltr"
              />
              {sensitiveChanged && (
                <p className="text-xs text-amber-600 flex items-center gap-1">
                  <Shield className="w-3 h-3 shrink-0" />
                  تغيير البريد أو الجوال يتطلب التحقق بكلمة المرور ورمز OTP
                </p>
              )}
            </div>

            {/* Password change toggle */}
            <button
              type="button"
              onClick={() => { setShowPwSection(v => !v); setCurrentPw(""); setNewPw(""); setConfirmPw(""); }}
              className="flex items-center gap-2 text-sm font-medium text-primary hover:underline"
            >
              <Lock className="w-4 h-4" />
              {showPwSection ? "إلغاء تغيير كلمة المرور" : "تغيير كلمة المرور"}
            </button>

            {showPwSection && (
              <div className="rounded-xl border border-border bg-muted/30 p-4 space-y-3">
                {/* Current password */}
                <div className="space-y-1.5">
                  <label className="text-sm font-semibold">كلمة المرور الحالية <span className="text-destructive">*</span></label>
                  <div className="relative">
                    <Input type={showCurPw ? "text" : "password"} value={currentPw} onChange={(e) => setCurrentPw(e.target.value)} className="text-right pl-10" placeholder="••••••••" />
                    <button type="button" onClick={() => setShowCurPw(v => !v)} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground" tabIndex={-1}>
                      {showCurPw ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>
                </div>
                {/* New password */}
                <div className="space-y-1.5">
                  <label className="text-sm font-semibold">كلمة المرور الجديدة</label>
                  <div className="relative">
                    <Input type={showNewPw ? "text" : "password"} value={newPw} onChange={(e) => setNewPw(e.target.value)} className="text-right pl-10" placeholder="٦ أحرف على الأقل" />
                    <button type="button" onClick={() => setShowNewPw(v => !v)} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground" tabIndex={-1}>
                      {showNewPw ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>
                </div>
                {/* Confirm password */}
                <div className="space-y-1.5">
                  <label className="text-sm font-semibold">تأكيد كلمة المرور الجديدة</label>
                  <div className="relative">
                    <Input type={showConPw ? "text" : "password"} value={confirmPw} onChange={(e) => setConfirmPw(e.target.value)} className="text-right pl-10" placeholder="أعد كتابة كلمة المرور" />
                    <button type="button" onClick={() => setShowConPw(v => !v)} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground" tabIndex={-1}>
                      {showConPw ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                    </button>
                  </div>
                </div>
              </div>
            )}

            <Button onClick={handleSave} disabled={saving || !hasChanges || !fullName.trim()} className="w-full gap-2">
              {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle className="w-4 h-4" />}
              {sensitiveChanged ? "التحقق من الهوية وحفظ" : "حفظ التغييرات"}
            </Button>
          </>
        )}

        {/* ══════════ إعدادات الإشعارات عبر الواتساب ══════════ */}
        {secureStep === "idle" && (
          <div className="border-t border-border pt-5 space-y-4">
            {/* Header */}
            <div className="flex items-center gap-2">
              <svg className="w-4 h-4 text-green-500 flex-shrink-0" viewBox="0 0 24 24" fill="currentColor"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/></svg>
              <p className="text-sm font-bold text-foreground">إعدادات الإشعارات عبر الواتساب</p>
            </div>

            {/* Toggle 1: Review notifications */}
            <label className="flex items-start gap-3 cursor-pointer select-none">
              <div className="relative mt-0.5 flex-shrink-0">
                <input type="checkbox" checked={waReviewEnabled} onChange={(e) => setWaReviewEnabled(e.target.checked)} className="sr-only" />
                <div className={`w-10 h-6 rounded-full transition-colors ${waReviewEnabled ? "bg-green-500" : "bg-muted-foreground/30"} relative`}>
                  <div className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow transition-all ${waReviewEnabled ? "right-1" : "left-1"}`} />
                </div>
              </div>
              <div className="flex-1">
                <p className="text-sm font-semibold text-foreground">إشعارات التقييمات <span className="text-xs font-normal text-muted-foreground">(من الزبائن)</span></p>
                <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">تلقّي إشعار على الواتساب عند قيام أحد الزبائن بكتابة تقييم جديد لشاليهك.</p>
              </div>
            </label>

            {/* Toggle 2: News / platform subscribe */}
            <label className="flex items-start gap-3 cursor-pointer select-none">
              <div className="relative mt-0.5 flex-shrink-0">
                <input type="checkbox" checked={waSubscribe} onChange={(e) => setWaSubscribe(e.target.checked)} className="sr-only" />
                <div className={`w-10 h-6 rounded-full transition-colors ${waSubscribe ? "bg-green-500" : "bg-muted-foreground/30"} relative`}>
                  <div className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow transition-all ${waSubscribe ? "right-1" : "left-1"}`} />
                </div>
              </div>
              <div className="flex-1">
                <p className="text-sm font-semibold text-foreground">أخبار تكيّة والتذكيرات <span className="text-xs font-normal text-muted-foreground">(من المنصة)</span></p>
                <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">الاشتراك في أخبار تكيّة عبر الواتساب وتلقّي تذكيرات التجديد وعروض الاشتراك.</p>
              </div>
            </label>

            {/* Toggle 3: Support notifications */}
            <label className="flex items-start gap-3 cursor-pointer select-none">
              <div className="relative mt-0.5 flex-shrink-0">
                <input type="checkbox" checked={waSupportEnabled} onChange={(e) => setWaSupportEnabled(e.target.checked)} className="sr-only" />
                <div className={`w-10 h-6 rounded-full transition-colors ${waSupportEnabled ? "bg-green-500" : "bg-muted-foreground/30"} relative`}>
                  <div className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow transition-all ${waSupportEnabled ? "right-1" : "left-1"}`} />
                </div>
              </div>
              <div className="flex-1">
                <p className="text-sm font-semibold text-foreground">إشعارات الدعم الفني <span className="text-xs font-normal text-muted-foreground">(من المنصة)</span></p>
                <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">تلقّي إشعار على الواتساب فور رد فريق تكيّة على تذاكر الدعم والطلبات الخاصة بك.</p>
              </div>
            </label>

            {/* Unified phone number */}
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-foreground">رقم الواتساب</label>
              <input
                type="tel"
                placeholder="٠٥xxxxxxxx"
                value={toArabicDigits(waUnifiedPhone)}
                onChange={(e) => setWaUnifiedPhone(e.target.value)}
                dir="rtl"
                className="w-full h-9 px-3 rounded-lg border border-border bg-background text-sm text-right focus:outline-none focus:ring-1 focus:ring-primary"
              />
            </div>

            {/* Save button */}
            <div className="flex justify-end">
              <button
                onClick={saveWaSettings}
                disabled={savingWa}
                className="flex items-center gap-1.5 text-sm font-semibold bg-primary text-primary-foreground px-5 py-2 rounded-lg hover:bg-primary/90 transition-colors disabled:opacity-50"
              >
                {savingWa ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : null}
                حفظ الإعدادات
              </button>
            </div>
          </div>
        )}

        {/* ══════════ Calendar Preferences ══════════ */}
        {secureStep === "idle" && (
          <div className="border-t border-border pt-5 space-y-4">
            <div className="flex items-center gap-2 mb-1">
              <Calendar className="w-4 h-4 text-primary" />
              <p className="text-sm font-bold text-foreground">تفضيلات التقويم</p>
            </div>
            <p className="text-xs text-muted-foreground -mt-2">
              اختر نوع التقويم الافتراضي لكل قسم عند تسجيل الدخول. يمكنك دائماً التبديل لحظياً من داخل كل قسم.
            </p>
            {/* Calendar default: Booking grid */}
            <div className="space-y-1.5">
              <label className="text-sm font-semibold">التقويم الأساسي للحجوزات</label>
              <div className="flex rounded-lg border border-border overflow-hidden text-sm w-fit">
                {(["hijri", "gregorian"] as const).map(v => (
                  <button
                    key={v}
                    type="button"
                    onClick={() => {
                      setBookingsCalPrefLocal(v);
                      localStorage.setItem("dashCalDefaultType", v);
                      apiFetch("/owner/profile/calendar-prefs", { method: "PATCH", body: JSON.stringify({ bookingsCalPref: v }) });
                    }}
                    className={`px-4 py-2 font-semibold transition-colors ${bookingsCalPrefLocal === v ? "bg-primary text-primary-foreground" : "bg-background text-muted-foreground hover:bg-muted"}`}
                  >{v === "hijri" ? "هجري" : "ميلادي"}</button>
                ))}
              </div>
              <p className="text-[11px] text-muted-foreground">يحدد نوع التقويم في تبويب «التقويم» عند بدء الجلسة.</p>
            </div>
            {/* Calendar default: Financial reports */}
            <div className="space-y-1.5">
              <label className="text-sm font-semibold">التقويم الأساسي للتقارير المالية</label>
              <div className="flex rounded-lg border border-border overflow-hidden text-sm w-fit">
                {(["gregorian", "hijri"] as const).map(v => (
                  <button
                    key={v}
                    type="button"
                    onClick={() => {
                      setReportsCalPrefLocal(v);
                      localStorage.setItem("revCalType", v);
                      apiFetch("/owner/profile/calendar-prefs", { method: "PATCH", body: JSON.stringify({ reportsCalPref: v }) });
                    }}
                    className={`px-4 py-2 font-semibold transition-colors ${reportsCalPrefLocal === v ? "bg-primary text-primary-foreground" : "bg-background text-muted-foreground hover:bg-muted"}`}
                  >{v === "hijri" ? "هجري" : "ميلادي"}</button>
                ))}
              </div>
              <p className="text-[11px] text-muted-foreground">يحدد نوع التقويم في تبويب «التقارير المالية» عند بدء الجلسة.</p>
            </div>
            {/* Salary calendar preference */}
            <div className="space-y-1.5">
              <label className="text-sm font-semibold">نظام الرواتب المعتمد</label>
              <div className="flex rounded-lg border border-border overflow-hidden text-sm w-fit">
                {(["gregorian", "hijri"] as const).map(v => (
                  <button
                    key={v}
                    type="button"
                    onClick={() => {
                      setSalaryCalPrefLocal(v);
                      localStorage.setItem("staffCalDefault", v);
                      window.dispatchEvent(new CustomEvent("salaryCalPrefChanged", { detail: v }));
                      apiFetch("/owner/profile/calendar-prefs", { method: "PATCH", body: JSON.stringify({ salaryCalPref: v }) });
                    }}
                    className={`px-4 py-2 font-semibold transition-colors ${salaryCalPrefLocal === v ? "bg-primary text-primary-foreground" : "bg-background text-muted-foreground hover:bg-muted"}`}
                  >{v === "hijri" ? "هجري" : "ميلادي"}</button>
                ))}
              </div>
              <p className="text-[11px] text-muted-foreground">يحدد نوع التقويم في قسم الموظفين وجداول الرواتب عند بدء الجلسة.</p>
            </div>
          </div>
        )}

        {/* ══════════ Step 1: Password verification ══════════ */}
        {secureStep === "password" && (
          <div className="space-y-5">
            <div className="flex items-start gap-3 bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-800/40 rounded-xl p-4">
              <Shield className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
              <div className="text-sm text-amber-800 dark:text-amber-300 leading-relaxed">
                <p className="font-semibold mb-1">التحقق من الهوية مطلوب</p>
                <p>لحماية حسابك، أدخل كلمة المرور الحالية لتأكيد هويتك قبل تغيير {emailChanged ? "البريد الإلكتروني" : "رقم الجوال"}.</p>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold">كلمة المرور الحالية <span className="text-destructive">*</span></label>
              <div className="relative">
                <Input
                  type={showSecPw ? "text" : "password"}
                  value={securePw}
                  onChange={(e) => setSecurePw(e.target.value)}
                  className="text-right pl-10"
                  placeholder="••••••••"
                  autoFocus
                  onKeyDown={(e) => { if (e.key === "Enter") handleSendOtp(); }}
                />
                <button type="button" onClick={() => setShowSecPw(v => !v)} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground" tabIndex={-1}>
                  {showSecPw ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            <div className="flex gap-3">
              <Button variant="outline" className="flex-1" onClick={cancelSecure} disabled={sendingOtp}>إلغاء</Button>
              <Button className="flex-1 gap-2" onClick={handleSendOtp} disabled={sendingOtp || !securePw}>
                {sendingOtp ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
                التحقق وإرسال الرمز
              </Button>
            </div>
          </div>
        )}

        {/* ══════════ Step 2: OTP verification ══════════ */}
        {secureStep === "otp" && (
          <div className="space-y-5">
            <div className="flex items-start gap-3 bg-green-50 dark:bg-green-950/20 border border-green-200 dark:border-green-800/40 rounded-xl p-4">
              <CheckCircle className="w-5 h-5 text-green-600 shrink-0 mt-0.5" />
              <div className="text-sm leading-relaxed">
                <p className="font-semibold text-green-800 dark:text-green-300 mb-1">تم إرسال رمز التحقق</p>
                <p className="text-green-700 dark:text-green-400">
                  تم إرسال الرمز إلى: <span className="font-bold text-foreground" dir="ltr">{otpSentTo}</span>
                </p>
                <p className="text-xs text-muted-foreground mt-1">الرمز صالح لمدة ١٠ دقائق</p>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-sm font-semibold">رمز التحقق <span className="text-destructive">*</span></label>
              <Input
                value={secureOtp}
                onChange={(e) => setSecureOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
                className="text-center tracking-[0.5em] text-xl font-bold"
                placeholder="000000"
                inputMode="numeric"
                maxLength={6}
                autoFocus
                onKeyDown={(e) => { if (e.key === "Enter" && secureOtp.length === 6) handleVerifyAndSave(); }}
              />
            </div>

            <div className="flex gap-3">
              <Button variant="outline" className="flex-1" onClick={cancelSecure} disabled={verifyingOtp}>إلغاء</Button>
              <Button className="flex-1 gap-2" onClick={handleVerifyAndSave} disabled={verifyingOtp || secureOtp.length < 6}>
                {verifyingOtp ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle className="w-4 h-4" />}
                تأكيد وحفظ التغييرات
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
